/**
 * REQ-0414 — developer live-token editor: registry + pure helpers.
 *
 * This module is the data layer behind the DEV-ONLY token editor panel
 * (`components/dev-token-editor`).  It is import-guarded by
 * `import.meta.env.DEV` at the mount site, so nothing here ships in an
 * end-user build.
 *
 * Design intent (REQ-0414 §1):
 *   - Controls are auto-generated by looping a declarative group registry;
 *     no per-token JSX is hand-written.
 *   - The item list is NOT hardcoded to fixed *values* — every current value
 *     is read live from the running document (see `dev-token-live.ts`), and
 *     the colour groups reconcile their membership against the variables
 *     actually declared on `:root` (`discoverRootVarNames` + `driftFor`) so a
 *     newly-added `--text-*` / `--surface-*` / `--border-*` / `--primary*`
 *     token surfaces automatically instead of going stale.
 *
 * All exports here are PURE (registry data + string maths).  DOM-touching
 * helpers (probe reads, `:root` overrides) live in `dev-token-live.ts` so the
 * conversions can be unit-tested without a browser.
 */

export type DevTokenKind = 'color' | 'size' | 'alpha'

export interface DevTokenGroupSpec {
  /** Stable id (also used as React key). */
  id: string
  /** English label — this is a developer tool, so no i18n. */
  title: string
  kind: DevTokenKind
  /**
   * COLOR groups: ordered, curated member var names (without the leading
   * `--`).  Rendered in this order.  `discoverPrefixes` is used to detect
   * drift — any `:root` var matching a prefix but missing from `members`
   * is reported by `driftFor` and appended by `orderedColorMembers`.
   */
  members?: string[]
  discoverPrefixes?: string[]
  /**
   * SIZE groups: the Tailwind type-scale names.  Each is backed by a
   * `--fs-<name>` variable (see tailwind.config.ts, REQ-0414) and rendered
   * with the Tailwind class `text-<name>`.
   */
  sizes?: string[]
  /**
   * ALPHA groups (REQ-0526): plain 0–1 `:root` variables, edited as numbers
   * rather than colours.  `alphas[].name` is the var name without `--`;
   * `label` is what the panel shows.
   *
   * Why this kind exists: judging a state colour means moving the hue AND the
   * weights it is used at together, and a weight baked into a Tailwind class
   * (`bg-row-edited/70`) cannot move at runtime.  Lifting those weights into
   * vars is what makes them tunable — see globals.css `--row-edited-*-alpha`.
   */
  alphas?: { name: string; label: string }[]
}

